import os
import requests

BASE_URL = "https://api.spotify.com/v1"
headers = {"Authorization": f"Bearer {os.environ['SPOTIFY_ACCESS_TOKEN']}"}

response = requests.get(
    f"{BASE_URL}/me/player/recently-played",
    headers=headers,
    params={"limit": 1},
)
response.raise_for_status()
items = response.json().get("items", [])

if items:
    artist_ids = [
        artist["id"]
        for artist in items[0]["track"].get("artists", [])
        if artist.get("id")
    ]
    if artist_ids:
        follow_response = requests.put(
            f"{BASE_URL}/me/following",
            headers=headers,
            params={"type": "artist", "ids": ",".join(artist_ids)},
        )
        follow_response.raise_for_status()

