import os
import requests

token = os.environ["SPOTIFY_ACCESS_TOKEN"]
headers = {"Authorization": f"Bearer {token}"}
base_url = "https://api.spotify.com/v1"

playlists_response = requests.get(
    f"{base_url}/me/playlists",
    headers=headers,
    params={"limit": 50},
)
playlists_response.raise_for_status()

playlist = next(
    (
        item
        for item in playlists_response.json().get("items", [])
        if item.get("name") == "My R&B"
    ),
    None,
)
if playlist is None:
    raise ValueError("Playlist 'My R&B' was not found.")

playlist_id = playlist["id"]

tracks_response = requests.get(
    f"{base_url}/playlists/{playlist_id}/tracks",
    headers=headers,
    params={"limit": 100},
)
tracks_response.raise_for_status()

track_items = tracks_response.json().get("items", [])
while track_items:
    requests.delete(
        f"{base_url}/playlists/{playlist_id}/tracks",
        headers=headers,
        json={
            "tracks": [
                {"uri": item["track"]["uri"]}
                for item in track_items
                if item.get("track") and item["track"].get("uri")
            ]
        },
    ).raise_for_status()

    next_url = tracks_response.json().get("next")
    if not next_url:
        break
    tracks_response = requests.get(next_url, headers=headers)
    tracks_response.raise_for_status()
    track_items = tracks_response.json().get("items", [])

requests.put(
    f"{base_url}/playlists/{playlist_id}",
    headers={**headers, "Content-Type": "application/json"},
    json={"name": "Test"},
).raise_for_status()

